-- S13: independent Claude attestation; exact package hash; only AUTO; no legacy mutation.
BEGIN;
DO $s13$
DECLARE p jsonb; e record; h text; val jsonb; ans jsonb; cd text; n int:=0; pub int:=0; links int:=0; b_leg jsonb; b_dep jsonb; lid int; residual text; diff text; old_desc text; new_desc text;
BEGIN
 SELECT jsonb_agg(to_jsonb(t) ORDER BY id) INTO b_leg FROM lf_ops.reglas t;
 SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones t;
 FOR p IN SELECT value FROM jsonb_array_elements($pack$[{"codigo":"S13-C01","version":1,"eval_id":995,"hash_version_atestado":"76b2e7cc3d18c9b82c508d136bf38f8b34dd8d7768b36d9ebbacd52f14dd4b74","hash_paquete_atestado":"c735ed7ba26005530cdcc04c9fc1394945a73f0629285b1dc6bc15bab3a6c62c","veredicto":"PASS","juez":"Claude independiente 2026-11-24 09:20 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":477,"familia":"THEME_LIGHT_DARK_SYSTEM","diferencias":"Contraste funcional: BLOQUEAR presentación B2B sin resolver tema efectivo antes de renderizar: preferencia persistida explícita prevalece sobre sistema y, sin señal resoluble, LIGHT. Referenciar bindings canónicos LIGHT/DARK sin duplicar colores ni medidas; DARK requiere QA antes de promoción.","residual":"","complementa":null},{"codigo":"S13-C02","version":1,"eval_id":996,"hash_version_atestado":"7c77e35e2a990c11219c3c7c10fd879f9c45ecc132c20128722443af407c8ed7","hash_paquete_atestado":"6b55d559234686be8ff9ff59e694cfadc53c48784bc7fd539c6d2207ab991624","veredicto":"PASS","juez":"Claude independiente 2026-11-24 09:20 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":485,"familia":"ROUTING_NAVIGATION","diferencias":"Contraste funcional: BLOQUEAR presentación ONB_001 WEB sin Ayuda, Política de Privacidad y Términos y Condiciones, o MOBILE sin Ayuda; no inventar URLs ni route_ids para destinos sin ruta canónica.","residual":"","complementa":null},{"codigo":"S13-C03","version":1,"eval_id":997,"hash_version_atestado":"e32a988bde88d8622070822ecc34f7632e60c40c223e994acfaa41de9c2e7621","hash_paquete_atestado":"fa2ac373a31775d00404c006d0823c4a053820509f7e9453d3303ac4924d8a04","veredicto":"PASS","juez":"Claude independiente 2026-11-24 09:20 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":486,"familia":"UI_MESSAGES","diferencias":"Contraste funcional: BLOQUEAR copy ONB_002 que afirme que el OTP por sí solo verifica identidad civil o que no comunique control o acceso al celular.","residual":"","complementa":null},{"codigo":"S13-C05","version":1,"eval_id":999,"hash_version_atestado":"647f05489c94cf7bfc2a386aa3d18587569d86adf876a92eeb7b012bedd3e324","hash_paquete_atestado":"15c5cb75185d9ddd46bd329101dea35a6d1958e009f23cf1150c174ead05ca47","veredicto":"PASS","juez":"Claude independiente 2026-11-24 09:20 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":547,"familia":"PRIVACY_PII","diferencias":"Contraste funcional: BLOQUEAR HOME_001 preautenticado que capture PII, consulte existencia de cuenta u ofertas, muestre deuda personalizada o use identificadores de cuenta; CTA expresa intención de iniciar flujo, no resultado.","residual":"","complementa":null},{"codigo":"S13-C06","version":1,"eval_id":1000,"hash_version_atestado":"140fb0f2bacd4c34fe4b37b71d87f55044b4d4035e7d7fcea48cd81311fc5743","hash_paquete_atestado":"c6927f8efec01e4b8c96dd72a7afd3b8854b22c4466361ce74b5c79cca66a16f","veredicto":"PASS","juez":"Claude independiente 2026-11-24 09:20 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":549,"familia":"PRIVACY_PII","diferencias":"Contraste funcional: BLOQUEAR HOME_RUTA_CLARIDAD que solicite PII, consulte cuentas/deudas/ofertas o personalice contenido educativo por estado de cuenta; al reutilizarla en Home autenticado, personalización pertenece al Home y no al contenido.","residual":"","complementa":null},{"codigo":"S13-C07","version":1,"eval_id":1001,"hash_version_atestado":"e887a1ee8206a6b6e0db3cace13bf99f964ca7c85f60f05ad74689a492fcde95","hash_paquete_atestado":"92a95a0f13e605672e0af984140626fd5be52c47aadbb4e9f0c733118409a1ec","veredicto":"PASS","juez":"Claude independiente 2026-11-24 09:20 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":553,"familia":"PRIVACY_PII","diferencias":"Contraste funcional: BLOQUEAR tarjetas o popups HOME_APRENDA_ANTES_DECIDIR que capturen PII, consulten cuenta/deuda/oferta o muestren datos personalizados; CTA de revisión inicia ONB_001, no consulta backend directa.","residual":"","complementa":null},{"codigo":"S13-C08","version":1,"eval_id":1002,"hash_version_atestado":"8c717291695e69f88f0f4486eadd6b9a4ecd98ef1846a24e367011b491c240eb","hash_paquete_atestado":"0a32796f1e9e42b5de753aa309909f1f74f32b7baebd07e2241ea1828edc9de1","veredicto":"PASS","juez":"Claude independiente 2026-11-24 09:20 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":576,"familia":"CONFLICT_PRECEDENCE","diferencias":"Contraste funcional: BLOQUEAR contrato visual B2B de autenticación preoperativa que exija divulgación contraria a seguridad/arquitectura; reconciliar conflicto antes de generar evidencia; LF_DS_V1 gobierna estilo, no autorización de exposición.","residual":"","complementa":null},{"codigo":"S13-C09","version":1,"eval_id":1003,"hash_version_atestado":"eceaf4b269b79fdc02db82a898cbadfd5205970d9d58962f338ea1282ca96fac","hash_paquete_atestado":"6b1d67d8a6390b7bcb2721debff9f6cda157f73d38d77cd52528cdc43803369f","veredicto":"PASS","juez":"Claude independiente 2026-11-24 09:20 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":581,"familia":"STATES","diferencias":"Contraste funcional: BLOQUEAR wizard B2B-CARGA-002 que convierta Cartera preparada en paso adicional o procesamiento definitivo, confunda estado UI con UPLOAD_BATCH o mutaciones fuera de lf_ops.estados_transiciones. Mantener secuencia seleccionar tipo/formato, subir/preparar, validar/resultado; mapeo condicional según formato LF o mapeo gobernado de empresa; resultado conserva B2B_LOAD_VALIDADO y salida detalle/historial.","residual":"","complementa":null},{"codigo":"S13-C16","version":1,"eval_id":1010,"hash_version_atestado":"f454f7ef067e1377a1ea5ac4a5a5c0f07775a40ed6a9f96a65252580650f7418","hash_paquete_atestado":"46f3f182a39abc3c89d4eb637180bb50d490693e379b107674c5e795038cdd63","veredicto":"PASS","juez":"Claude independiente 2026-11-24 09:20 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":0.8,"observacion":"Omite estructura base de bloques: saludo/contexto, siguiente acción principal, situaciones coexistentes, beneficio/campaña, orientación y ayuda contextual."},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":601,"familia":"LOADING_EMPTY_ERROR_STATES","diferencias":"Contraste funcional: BLOQUEAR composición de Inicio que muestre bloque sin dato autoritativo/no aplicable, deje espacio vacío tras ocultarlo o permita beneficio/campaña desplazar acción financiera P0/P1; jerarquía de bloques según contexto server-side. Observación del juez: Omite estructura base de bloques: saludo/contexto, siguiente acción principal, situaciones coexistentes, beneficio/campaña, orientación y ayuda contextual.","residual":"","complementa":null},{"codigo":"S13-C17","version":1,"eval_id":1011,"hash_version_atestado":"9ab4dc3760c4ece11a819a0da2097ac530ae97a6d2c2eebbd7898be8ab0d2982","hash_paquete_atestado":"ce8379f20f6b014ff16e0b9e3dce8120d2ff0e07d862c9bba0bb3ce9961ad393","veredicto":"PASS","juez":"Claude independiente 2026-11-24 09:20 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":655,"familia":"TRANSITIONS","diferencias":"Contraste funcional: BLOQUEAR transición AUTH_FLOW B2B no registrada en lf_ops.estados_transiciones o impuesta por cliente; servidor determina origen/destino y resultado; MFA_REQUIRED/AUTHENTICATED proyectan estado y INVALID_CREDENTIALS/RATE_LIMITED/ACCESS_DENIED/SERVICE_UNAVAILABLE preservan estado no autenticado o MFA vigente según corresponda.","residual":"","complementa":null}]$pack$::jsonb) LOOP
 cd:=p->>'codigo'; lid:=(p->>'legada_id')::int;
 SELECT id,regla,version,hash_paquete INTO e FROM lf_ops.nucleo_evaluaciones WHERE regla=cd AND version=(p->>'version')::int ORDER BY id DESC LIMIT 1;
 IF ((SELECT count(*) FROM lf_ops.reglas)=586 AND e.id IS DISTINCT FROM (p->>'eval_id')::bigint) OR e.hash_paquete IS DISTINCT FROM p->>'hash_paquete_atestado' OR (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=e.version)<>8 OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=e.version AND estado='CANDIDATA' AND hash=p->>'hash_version_atestado') THEN RAISE EXCEPTION 'S13_ATTESTATION_DRIFT %',cd; END IF;
 h:=lf_ops.nucleo_hash_paquete_v1(cd,e.version);
 IF h IS DISTINCT FROM e.hash_paquete THEN RAISE EXCEPTION 'S13_HASH_DRIFT %',cd; END IF;
 val:=jsonb_build_object('regla',cd,'hash_evaluado',h,'veredicto',p->>'veredicto','puntajes',p->'puntajes','juez',p->>'juez','modo','INDEPENDIENTE','revisor_es_productor',false,'llamadas_modelo',1,'evidencia_ref','sandbox/lf_contract_gate_test/nucleo_ci/nucleo_s13_juicios_17_v1.json#'||cd);
 BEGIN
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val||jsonb_build_object('hash_evaluado',repeat('0',64)));
 RAISE EXCEPTION 'S13_NEGATIVE_HASH_ACCEPTED %',cd;
 EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF; END;
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val);
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 IF ans->>'decision'<>'AUTO' THEN RAISE EXCEPTION 'S13_NOT_AUTO % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_promover_v1(cd);
 IF ans->>'resultado'<>'PROMOVIDA_AUTO' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=e.version AND estado='PUBLICADA') THEN RAISE EXCEPTION 'S13_PROMOTION_FAIL % %',cd,ans; END IF;
 pub:=pub+1;
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
 IF EXISTS(SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada WHERE legacy_id=lid AND estado_cobertura='REEMPLAZADA') THEN RAISE EXCEPTION 'S13_COVERAGE_DRIFT %',lid; END IF;
 IF p->>'complementa' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada c JOIN lf_ops.nucleo_regla_versiones v ON v.regla=c.nucleo_codigo AND v.version=c.version_nucleo WHERE c.legacy_id=lid AND c.nucleo_codigo=p->>'complementa' AND c.estado_cobertura='PARCIAL' AND v.estado='PUBLICADA') THEN RAISE EXCEPTION 'S13_COMPLEMENT_DRIFT %',lid; END IF;
 SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=lid;
 SELECT descripcion INTO new_desc FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=e.version;
 residual:=coalesce(p->>'residual',''); diff:=p->>'diferencias'||CASE WHEN residual<>'' THEN ' Residual: '||residual ELSE '' END;
 INSERT INTO lf_ops.lf_nucleo_cobertura_legada(legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
 VALUES(lid,cd,e.version,CASE WHEN residual='' THEN 'REEMPLAZADA' ELSE 'PARCIAL' END,diff,jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||new_desc||' DIFERENCIA: '||diff,'residual',residual,'juicio','Claude independiente S13 2026-11-24 09:20','limite_aceptacion','Cobertura funcional; binding runtime no certificado'),h,'GPT / Claude S13 independiente');
 links:=links+1;
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S13_SOURCE_MISSING %',lid; END IF;
 n:=n+1;
 END LOOP;
 IF n<>10 OR pub<>10 OR ((SELECT count(*) FROM lf_ops.reglas)=586 AND links<>10) OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY id) FROM lf_ops.reglas t) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones t) IS DISTINCT FROM b_dep THEN RAISE EXCEPTION 'S13_READBACK_FAIL n=% pub=% links=%',n,pub,links; END IF;
 IF (SELECT count(*) FROM lf_ops.nucleo_regla_versiones WHERE regla IN ('S13-C04','S13-C10','S13-C11','S13-C12','S13-C13','S13-C14','S13-C15') AND estado='CANDIDATA' AND version=1)<>7 OR EXISTS(SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada WHERE nucleo_codigo IN ('S13-C04','S13-C10','S13-C11','S13-C12','S13-C13','S13-C14','S13-C15')) THEN RAISE EXCEPTION 'S13_DEFERRED_DRIFT'; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S13_DPIG03_FAIL'; END IF;
 RAISE NOTICE 'S13_PASS 10 JUICIOS 10 AUTO links=% DPIG03=0',links;
END $s13$;
COMMIT;
